'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString('en-US');
const cache=new Map();let routeToken=0,detailToken=0,dispose=()=>{};
async function get(path){if(cache.has(path))return cache.get(path);const packed=path.startsWith('code/')||path.startsWith('scripts/')||path.endsWith('.gz');const response=await fetch('data/research/'+path+((path.startsWith('code/')||path.startsWith('scripts/'))&&!path.endsWith('.gz')?'.gz':''));if(!response.ok)throw Error('This collection could not be loaded.');const value=packed?await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).json():await response.json();cache.set(path,value);return value}
const table=(headers,rows)=>`<div class="research-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(typeof v==='object'?JSON.stringify(v):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const download=(name,label=name)=>`<a href="downloads/${encodeURIComponent(name)}" download>${esc(label)}</a>`;
function saveText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function errorHTML(){return '<div class="error-box">Unable to load this collection. Check your connection and <button onclick="location.reload()">try again</button>.</div>'}
function sourceViewer(host,text,name,line=0){host.innerHTML=`<div class="source-controls"><input type="search" placeholder="Find in this file…" aria-label="Find in source"><button data-wrap>Wrap lines</button><button data-save>Download file</button></div><p class="research-status" data-matches></p><pre class="source-code" tabindex="0" aria-label="File contents"></pre>`;const pre=host.querySelector('pre'),input=host.querySelector('input');let timer;
 const render=()=>{const q=input.value.toLowerCase();let matches=0;pre.innerHTML=text.split('\n').map((s,i)=>{const hit=q&&s.toLowerCase().includes(q);if(hit)matches++;return `<span class="source-line ${hit?'hit':''}" data-line="${i+1}"><span class="line-number">${i+1}</span>${esc(s)}</span>`}).join('');host.querySelector('[data-matches]').textContent=q?`${fmt(matches)} matching lines`:`${fmt(text.split('\n').length)} lines · displayed as recovered`;if(q)pre.querySelector('.hit')?.scrollIntoView({block:'nearest'});};render();input.oninput=()=>{clearTimeout(timer);timer=setTimeout(render,180)};host.querySelector('[data-wrap]').onclick=e=>{pre.classList.toggle('wrap');e.target.textContent=pre.classList.contains('wrap')?'Unwrap lines':'Wrap lines'};host.querySelector('[data-save]').onclick=()=>saveText(text,name);if(line){const target=pre.querySelector(`[data-line="${line}"]`);target?.classList.add('hit');if(target)pre.scrollTop=target.offsetTop-pre.offsetTop-35}}
function collection(data,{placeholder='Search this collection…',title,subtitle,search,detail,filters=[],links=''}){
 $('#view').innerHTML=`${links}<div class="research-controls"><label class="wide">Search<input id="collection-search" type="search" placeholder="${esc(placeholder)}"></label>${filters.map((f,i)=>`<label>${esc(f.label)}<select data-filter="${i}"><option value="">All</option>${f.values.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div><p class="research-status" id="collection-status"></p><div class="research-split"><div><div class="research-list" id="collection-list"></div><div class="research-pagination"><button id="collection-prev">← Previous</button><span id="collection-page"></span><button id="collection-next">Next →</button></div></div><div class="research-detail" id="collection-detail">Select an entry to inspect it.</div></div>`;
 let page=0,filtered=data,chosen=null,timer;const size=50;
 const render=()=>{$('#collection-status').textContent=`${fmt(filtered.length)} of ${fmt(data.length)} entries`;$('#collection-list').innerHTML=filtered.slice(page*size,(page+1)*size).map((r,i)=>`<button data-row="${i}" class="${r===chosen?'active':''}">${esc(title(r))}<small>${esc(subtitle(r))}</small></button>`).join('')||'<p class="research-box">No matching entries.</p>';$('#collection-page').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/size)}`;$('#collection-prev').disabled=page===0;$('#collection-next').disabled=(page+1)*size>=filtered.length};
 const apply=()=>{const q=$('#collection-search').value.trim().toLowerCase();filtered=data.filter(r=>(!q||search(r).toLowerCase().includes(q))&&filters.every((f,i)=>{const v=$(`[data-filter="${i}"]`).value;return !v||f.value(r)===v}));page=0;render();const p=new URLSearchParams({section:location.hash.slice(1),q:$('#collection-search').value});filters.forEach((_,i)=>p.set('f'+i,$(`[data-filter="${i}"]`).value));history.replaceState(null,'','?'+p+location.hash)};
 async function choose(row){chosen=row;render();const p=new URLSearchParams(location.search);p.set('section',location.hash.slice(1));p.set('entry',String(data.indexOf(row)));if(row.path&&location.hash==='#evidence')p.set('file',row.path);history.replaceState(null,'','?'+p+location.hash);const ticket=++detailToken;const host=$('#collection-detail');host.textContent='Loading details…';try{await detail(chosen,host,()=>ticket===detailToken)}catch{if(ticket===detailToken)host.innerHTML=errorHTML()}}
 $('#collection-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(apply,150)};document.querySelectorAll('[data-filter]').forEach(s=>s.onchange=apply);$('#collection-prev').onclick=()=>{page--;render()};$('#collection-next').onclick=()=>{page++;render()};$('#collection-list').onclick=e=>{const button=e.target.closest('[data-row]');if(button)choose(filtered[page*size+Number(button.dataset.row)])};dispose=()=>clearTimeout(timer);const params=new URLSearchParams(location.search);if(params.get('section')===location.hash.slice(1)){$('#collection-search').value=params.get('q')||'';filters.forEach((_,i)=>$(`[data-filter="${i}"]`).value=params.get('f'+i)||'');apply()}else render();const selectedFile=params.get('file');const row=location.hash==='#evidence'&&selectedFile?data.find(r=>r.path===selectedFile):params.get('section')===location.hash.slice(1)&&params.has('entry')?data[Number(params.get('entry'))]:null;if(row)choose(row);

}
function findings(){
 $('#view').innerHTML=`<div class="research-links"><a href="#xp">Explore XP requirements →</a><a href="index.html#static-items">Browse items →</a><a href="#scripts">Read recovered code →</a></div><div class="research-cards">${[['15,278','Files in the historical 3.54.0 audit'],['130','Static files decoded: 125 JSON tables + 5 cache containers'],['7,129','Lua scripts decrypted and available to read'],['2,050 / 2,051','Maps decoded; one test map remains unresolved'],['4,281','Unity archives in the current inventory'],['293,384','Methods indexed in historical 3.54.0 research']].map(([n,t])=>`<div class="research-card"><strong>${n}</strong><p>${t}</p></div>`).join('')}</div>
 <article class="research-box"><p class="eyebrow">WHAT WE CAN NOW EXPLAIN</p><h2>Progression, combat, and game behavior</h2><p>The archive now includes XP and cumulative thresholds, evolution and limit-break costs, weapon upgrades, guardian levels, buffs, AI configurations, items, quests, projectiles, and stage definitions. The original 187,988 cache records are still available.</p><p>The Lua collection contains combat routines, quest controllers, story sections, mini-games, and corrective scripts. These are recovered source files. The compiled-code index supplies class and method names and addresses; it is not a reconstruction of the original C# source.</p><div class="research-links"><a href="index.html#static-exps2">XP data</a><a href="index.html#static-weaponenhance">Weapon upgrades</a><a href="index.html#static-guardianlevel">Guardian levels</a><a href="index.html#static-buffs">Buffs</a><a href="index.html#static-battleais">Battle AI</a><a href="index.html#static-elementalmatrix2">Elemental relations</a></div></article>
 <article class="research-box"><h2>How the files were opened</h2><ol><li><strong>Cache containers:</strong> the <code>k1ng</code> header led to a binary record index and LZ4 blocks. Most records were already JSON; localization IDs and text were assembled into JSON during extraction.</li><li><strong>Hidden metadata:</strong> the APK loader referenced <code>mscorlib.dll-resources.dat</code>. Reproducing its XOR routine recovered 39,087,964 bytes of IL2CPP metadata, including class and method names.</li><li><strong>Scripts:</strong> following <code>Oak.GameScriptDecrypt</code> revealed the AES-CBC key inputs. Removing PKCS7 padding and decompressing LZ4 produced Lua.</li><li><strong>Static tables:</strong> <code>Foundations.EncryptStream</code> derives a SHA-256 key from a header seed and a fixed prefix. AES-CBC decryption and DEFLATE decompression produced the tables.</li><li><strong>Maps:</strong> the loader derives a key from the map name. The decoded files have a <code>KONG</code> header; their complete internal object schema is still being investigated.</li></ol><p>No brute force or running game was needed. Each decoded script passed padding, output-length, compression, and UTF-8 checks. The five decrypted cache containers exactly match the earlier cache files.</p><details><summary>What does an index JSON mean?</summary><p><code>strings-bin-enUS.index.json</code> is an export created by the decoder, not an original hidden JSON file. IDs and lengths come from the binary index. Readable field labels were added during analysis, and uncertain meanings remain labelled as unknown.</p></details></article>
 <article class="research-box"><h2>Evidence and limits</h2><p>The metadata contains 36,384 types, 293,384 methods, 253,660 fields, and 51,120 string literals. Section bounds and method ownership were checked. For the game assembly, 192,140 methods were mapped to native addresses where available.</p><ul><li>Historical native research used a different APK distribution. The current 3.55.0 data import uses com.kakaogames.gdtskr; old native findings have not been revalidated.</li><li>IFix replacement branches and corrective Lua scripts can change behavior at runtime.</li><li>Table entries may describe unused, test, or platform-specific content. They do not prove a live feature is enabled.</li><li>Server-only rules are not present in these client files.</li><li>One test map remains encrypted; ten minimap coordinate-like files have an unconfirmed schema.</li></ul><p>Images, audio, videos, and shaders were inventoried, not exhaustively reviewed by sight or sound. Original APK binaries, account settings, and raw graphical assets are not part of this website.</p><div class="download-links">${download('offline-report-fr.md','Full offline report (French)')}${download('file-review-status.csv.gz','File-by-file review status (CSV.gz)')}</div></article>`;
}
async function xp(ticket){const [heroes,weapons,guardian]=await Promise.all([get('exps2.json'),get('weaponenhance.json'),get('guardianlevel.json')]);if(ticket!==routeToken)return;
 $('#view').innerHTML=`<p class="research-box">Values are stored <strong>internal level indices (0–219)</strong>, not verified UI levels. Rows beyond the playable cap can exist. This calculator follows the unpatched client’s cumulative-threshold rule; regional selection and runtime patches are not verified.</p><div class="research-controls"><label>Progression<select id="xp-kind"><option value="hero">Hero</option><option value="weapon">Weapon</option></select></label><label>Variant<select id="xp-variant"><option value="LevelExps">Default</option><option value="LevelExps.Kong">Kong</option><option value="LevelExps.Switch">Switch</option></select></label><label>From internal level<input id="xp-from" type="number" min="0" max="219" value="0"></label><label>To internal level<input id="xp-to" type="number" min="0" max="219" value="99"></label><button id="xp-download">Download this table</button></div><div id="xp-result" class="xp-result" role="status"></div><div id="xp-table"></div><article class="research-box"><h2>How the calculation works</h2><p>For an internal target level L, the threshold is zero at L = 0, otherwise <code>TotalExps[L − 1]</code>. The calculator subtracts the starting threshold from the target threshold, assuming no partial XP at the starting level.</p><p>The hero client methods also compute remaining XP as <code>TotalExps − current XP</code>, and progress within the selected band as <code>1 − (TotalExps − current XP) / Exps</code>. All six hero/weapon table variants passed cumulative-sum checks.</p><div class="download-links">${download('Oak.ExpsDataLevelExpExtensions.asm','Read the native XP evidence')}${download('Oak.LevelExpSpec.asm','Read the field accessors')}</div><div class="research-links"><a href="index.html#static-exps2">Evolution, limit breaks & caps</a><a href="index.html#static-weaponenhance">All weapon upgrade rules</a><a href="index.html#static-guardianlevel">${fmt(guardian.GuardianLevel.length)} guardian-level rows</a></div></article>`;
 const chosen=()=>($('#xp-kind').value==='hero'?heroes:weapons)[$('#xp-variant').value];
 const xpParams=new URLSearchParams(location.search);if(xpParams.get('section')==='xp'){for(const id of ['xp-kind','xp-variant','xp-from','xp-to'])if(xpParams.has(id)){const el=$('#'+id),v=xpParams.get(id);if(el.tagName!=='SELECT'||[...el.options].some(o=>o.value===v))el.value=v}}
 const update=()=>{const p=new URLSearchParams({section:'xp'});for(const id of ['xp-kind','xp-variant','xp-from','xp-to'])p.set(id,$('#'+id).value);history.replaceState(null,'','?'+p+'#xp');const data=chosen(),from=Number($('#xp-from').value),to=Number($('#xp-to').value);if(!$('#xp-from').value||!$('#xp-to').value||!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<from||to>219){$('#xp-result').textContent='Enter whole internal levels from 0 to 219, with the target at or above the start.'}else{const threshold=l=>l===0?0:data[l-1].TotalExps;$('#xp-result').innerHTML=`<strong>${fmt(threshold(to)-threshold(from))}</strong><span>XP from internal level ${from} to ${to}<br><small>Starting with no partial XP</small></span>`}const fields=Object.keys(data[0]);$('#xp-table').innerHTML=table(fields,data.map(row=>fields.map(k=>row[k])))};
 for(const id of ['xp-kind','xp-variant','xp-from','xp-to'])$('#'+id).oninput=update;$('#xp-download').onclick=()=>saveText(JSON.stringify(chosen(),null,2),`${$('#xp-kind').value}-${$('#xp-variant').value}.json`);update();
}
async function scripts(ticket){const data=await get('scripts.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search file paths or function names…',title:r=>r.path,subtitle:r=>`${fmt(r.lines)} lines · ${fmt(r.functions.length)} indexed functions`,search:r=>r.path+' '+r.functions.map(x=>x.name).join(' '),filters:[{label:'Category',values:[...new Set(data.map(r=>r.category))].sort(),value:r=>r.category}],detail:async(r,host,current)=>{const chunk=await get(`scripts/${r.chunk}.json`);if(!current())return;host.innerHTML=`<h2>${esc(r.path)}</h2><p class="research-status">Recovered Lua source · text-only viewing; never executed here.</p><label>Jump to function <select id="function-jump"><option value="0">Start of file</option>${r.functions.map(f=>`<option value="${f.line}">${esc(f.name)} · line ${f.line}</option>`).join('')}</select></label><div id="source-host"></div>`;sourceViewer($('#source-host'),chunk[r.id],r.path.split('/').pop());$('#function-jump').onchange=e=>{const pre=host.querySelector('pre'),line=pre.querySelector(`[data-line="${e.target.value}"]`);if(line){pre.querySelectorAll('.hit').forEach(x=>x.classList.remove('hit'));line.classList.add('hit');pre.scrollTop=line.offsetTop-pre.offsetTop-30}}}})}
async function code(ticket){const requestedMethod=new URLSearchParams(location.search).get('method');const data=await get('types.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search a class, e.g. DamageCalculator…',title:r=>r.name,subtitle:r=>`${r.assembly} · ${r.method_count} methods`,search:r=>r.name+' '+r.assembly,filters:[{label:'Assembly',values:[...new Set(data.map(r=>r.assembly))].sort(),value:r=>r.assembly}],links:'<p class="research-box">Select a class, then <strong>Read assembly</strong> on a mapped method to see the recovered instructions. Lua source is in its own section. This is not original C# source, and most methods have not been interpreted. <a href="research.html#evidence">Read analysis reports and supporting evidence →</a></p>',detail:async(r,host,current)=>{const chunk=await get(`code/${Math.floor(Number(r.index)/300)}.json`);if(!current())return;const d=chunk[r.index];host.innerHTML=`<h2>${esc(r.name)}</h2><p>${esc(r.assembly)}</p><label>Filter methods and fields<input id="method-filter" type="search" placeholder="e.g. GetDamage" style="width:100%;margin:10px 0"></label><div id="code-members"></div><div id="native-source"></div><button id="code-download">Download class index</button>`;const render=()=>{const q=$('#method-filter').value.toLowerCase();$('#code-members').innerHTML='<h3>Methods</h3><div class="native-methods">'+d.methods.filter(x=>x.name.toLowerCase().includes(q)).map(m=>`<p><strong>${esc(m.name)}</strong> <small>${m.parameter_count} parameters · ${esc(m.address)}</small> ${m.address&&m.address!=='0x0'&&m.address!=='unmapped'?`<button data-native="${m.index}">Read assembly</button>`:'<span class="research-status">No native body mapped</span>'}</p>`).join('')+'</div><details><summary>Stored fields</summary>'+table(['Name','Type index','Token'],d.fields.filter(x=>x.name.toLowerCase().includes(q)).map(x=>[x.name,x.type_index,x.token]))+'</details>'};$('#method-filter').oninput=render;let nativeTicket=0;$('#code-members').onclick=async e=>{const button=e.target.closest('[data-native]');if(!button)return;const nt=++nativeTicket;const target=$('#native-source');target.textContent='Loading native instructions…';try{const index=await get('native/index.json'),part=index.methods[button.dataset.native];if(part===undefined)throw Error('This method has no exported instructions.');const body=(await get('native/'+part+'.json.gz'))[button.dataset.native];if(!current()||nt!==nativeTicket)return;target.innerHTML=`<h3>${esc(body.name)}</h3><p class="native-warning">${esc(body.status)} · ${body.decodedBytes} decoded bytes of ${body.rangeBytes}</p><p>${esc(index.notice)}</p><div class="native-reader"></div>`;sourceViewer(target.querySelector('.native-reader'),body.text,body.name+'.asm');const p=new URLSearchParams(location.search);p.set('method',button.dataset.native);history.replaceState(null,'','?'+p+location.hash);target.scrollIntoView({block:'start'})}catch(e){if(current()&&nt===nativeTicket)target.textContent=e.message}};$('#code-download').onclick=()=>saveText(JSON.stringify({type:r,...d},null,2),'class-'+r.index+'.json');render();const method=requestedMethod;if(method&&/^\d+$/.test(method))host.querySelector(`[data-native="${method}"]`)?.click()}})}
function readableReport(text){return text.split(/\n\s*\n/).map(block=>{if(/^#{1,4} /.test(block)){const n=block.match(/^#+/)[0].length;return `<h${n+1}>${esc(block.replace(/^#+ /,''))}</h${n+1}>`}if(/^    |^\|/m.test(block))return '<pre>'+esc(block)+'</pre>';return '<p>'+esc(block).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')+'</p>'}).join('')}
async function evidence(ticket){const data=await get('evidence.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search reports, formulas or evidence files…',title:r=>r.name,subtitle:r=>r.category+' · '+fmt(r.bytes)+' bytes',search:r=>r.name+' '+r.path+' '+r.category,filters:[{label:'Evidence type',values:[...new Set(data.map(r=>r.category))],value:r=>r.category}],links:'<p class="research-box">Read the explanations, inspect the supporting code, or download the evidence. <a href="research.html?file=Reports-damage-formula.md#evidence">Start with the damage formula →</a>. For any mapped game method, use <a href="research.html#code">Compiled code & assembly</a>; for recovered Lua, use <a href="research.html#scripts">Lua source</a>. An available file is not necessarily a reviewed or proven game rule.</p>',detail:async(r,host,current)=>{host.innerHTML=`<h2>${esc(r.name)}</h2><p>${esc(r.note)}</p><p><a href="${esc(r.url)}" download>Download evidence file</a></p><div id="evidence-content"></div>`;if(r.category==='Download inventories'||r.bytes>2500000){$('#evidence-content').textContent='Download this inventory to inspect it. Large files are not loaded into the page.';return}const response=await fetch(r.url);if(!response.ok)throw Error('Evidence file unavailable');let text=await response.text();if(!current())return;if(r.path.endsWith('.json')){try{text=JSON.stringify(JSON.parse(text),null,2)}catch{}}const target=$('#evidence-content');if(r.path.endsWith('.md')){target.innerHTML='<article class="evidence-report">'+readableReport(text)+'</article><h3>Supporting native evidence</h3><div class="evidence-links">'+data.filter(e=>e.category==='Assembly'&&(r.path.includes('damage-formula')?/DamageCalculator|CharacterStatsBehaviour|CriticalDamage/.test(e.path):true)).map(e=>`<p><a href="research.html?file=${encodeURIComponent(e.path)}#evidence">${esc(e.name)}</a></p>`).join('')+'</div><details><summary>Original report text</summary><div class="report-source"></div></details>';sourceViewer(target.querySelector('.report-source'),text,r.path)}else sourceViewer(target,text,r.path)}})}

async function maps(ticket){const data=await get('maps.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search map names…',title:r=>r.path,subtitle:r=>r.status,search:r=>r.path+' '+r.status,filters:[{label:'Status',values:['Decoded','Unresolved'],value:r=>r.id===null?'Unresolved':'Decoded'}],links:'<div class="research-links"><a href="visual.html?tab=maps">Browse interactive maps →</a><a href="#bundles">Explore 4,281 Unity archives →</a></div><p class="research-status">Map references are strings extracted from decoded binaries. Their role and exact object relationships are not all confirmed.</p>',detail:async(r,host,current)=>{if(r.id===null){host.innerHTML='<h2>Unresolved test map</h2><p>The recovered decryption method fails padding validation for this file. No guessed output is presented.</p>';return}const refs=await get(`maps/${r.id}.json`);if(!current())return;host.innerHTML=`<h2>${esc(r.path)}</h2><p class="research-status">${fmt(r.bytes)} decoded bytes · KONG version ${r.version} · ${fmt(refs.length)} extracted strings. Full object schema remains partial.</p><div id="source-host"></div>`;sourceViewer($('#source-host'),refs.join('\n'),r.path.split('/').pop()+'.references.txt')}})}
async function bundles(ticket){const data=await get('bundles.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search archive paths or object types…',title:r=>r.path,subtitle:r=>`${fmt(r.objects)} objects · ${Object.keys(r.types).join(', ')}`,search:r=>r.path+' '+Object.keys(r.types).join(' '),links:`<p class="research-box">All archives were parsed. MonoBehaviour components can hold gameplay configuration. MonoScript objects describe class associations; they are not necessarily source code. Most TextAssets are Spine animation data. ${download('bundle-objects.csv.gz','Download the complete object inventory (CSV.gz)')}</p>`,detail:async(r,host)=>{host.innerHTML=`<h2>${esc(r.path)}</h2>${table(['Object type','Count'],Object.entries(r.types))}`}})}
async function events(ticket){const data=await get('events.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search story events…',title:r=>r.name,subtitle:r=>r.normalized?'Parsed after removing trailing commas in a copy':'Parsed JSON',search:r=>r.name,detail:async(r,host,current)=>{const d=await get(`events/${r.id}.json`);if(!current())return;host.innerHTML=`<h2>${esc(r.name)}</h2><p class="research-status">${r.normalized?'Trailing commas normalized; original preserved.':'Original event structure, formatted for reading.'}</p><div id="source-host"></div>`;sourceViewer($('#source-host'),JSON.stringify(d,null,2),r.name+'.json')}})}
async function audit(ticket){const data=await get('audit.json');if(ticket!==routeToken)return;collection(data,{placeholder:'Search file paths or review status…',title:r=>r.path,subtitle:r=>r.status,search:r=>r.path+' '+r.status,filters:[{label:'Review status',values:[...new Set(data.map(r=>r.status))].sort(),value:r=>r.status}],links:`<article class="research-box"><h2>Evidence you can take with you</h2><p>CSV.gz files are compressed CSV downloads. The audit covers all 15,278 supplied downloaded files. The separate APK inspection covered 2,716 archive entries. Fingerprinting does not mean every function was interpreted or every media file viewed.</p><div class="download-links">${[['file-review-status.csv.gz','File review'],['all-files.csv.gz','File hashes'],['table-catalog.csv.gz','Table catalog'],['lua-functions.csv.gz','Lua functions'],['managed-types.csv.gz','All types'],['managed-methods.csv.gz','All methods'],['managed-fields.csv.gz','All fields'],['game-method-addresses.csv.gz','Game method addresses'],['gameplay-methods.csv.gz','Gameplay methods'],['offline-report-fr.md','Full report (French)']].map(x=>download(...x)).join('')}</div></article>`,detail:async(r,host)=>{host.innerHTML=`<h2>${esc(r.path)}</h2><p>${esc(r.status)}</p><p class="research-status">Original size: ${fmt(r.bytes)} bytes. See the hash inventory download for its fingerprint.</p>`}})}
const routes={evidence:['Reports & code evidence','Read explanations and the files supporting them.',evidence],findings:['Research findings','What was recovered, how it was validated, and what remains uncertain.',findings],xp:['XP & progression','Inspect thresholds, compare variants, and calculate progression costs.',xp],scripts:['Lua source archive','Search 7,129 recovered files by path or indexed function name.',scripts],code:['Compiled code & assembly','Read the native instructions behind mapped game methods.',code],maps:['Maps & resources','Decoded map references and the remaining unknowns.',maps],bundles:['Unity archive inventory','Explore the contents of every inspected archive.',bundles],events:['Story events','Read the 114 event definitions and search within each file.',events],audit:['File audit & downloads','Trace each finding back to the inspected files.',audit]};
async function route(){dispose();const ticket=++routeToken;++detailToken;const key=location.hash.slice(1)||'findings',r=routes[key]||routes.findings;$('#view-title').textContent=r[0];$('#view-description').textContent=r[1];document.title=r[0]+' — Guardian Atlas';document.querySelectorAll('#research-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+key||(key==='bundles'&&a.getAttribute('href')==='#maps')));$('#view').innerHTML='<p class="research-box">Opening the archive…</p>';try{await r[2](ticket)}catch(e){if(ticket===routeToken)$('#view').innerHTML=errorHTML();console.error(e)}}window.addEventListener('hashchange',route);route();
